package com.rescuefarm.ui.checkout;import android.content.Context;import androidx.annotation.NonNull;import androidx.lifecycle.*;import com.rescuefarm.data.repository.OrderRepositoryFactory;public class OrderViewModelFactory implements ViewModelProvider.Factory{private final Context c;public OrderViewModelFactory(Context c){this.c=c.getApplicationContext();}@NonNull public <T extends ViewModel>T create(@NonNull Class<T> t){return (T)new OrderViewModel(OrderRepositoryFactory.create(c));}}
